  { title: 'Synchronization licensing', text: 'Applies when music is combined with films, television, advertisements, documentaries, online videos, games, campaigns, trailers, or other audiovisual productions.' },
  { title: 'Neighbouring rights', text: 'Relate primarily to recorded performances and sound recordings, and may provide income to performers and master owners when recordings are broadcast or publicly used.' }
