const checklist = [
  'Who wrote the song, and have the songwriting percentages been agreed?',
  'Is there a signed split sheet?',
  'Who owns the master recording?',
  'Are artist, producer, and publishing agreements documented?',
  'Is the metadata accurate and does the recording have the correct ISRC?',
  'Has the composition been registered where necessary?',
  'Is the recording distributed internationally?',
  'Are publishing and neighbouring rights being administered?',
  'Do you regularly review your royalty reports?',
  'Are contracts and statements stored safely?'
]

const faqs = [
  { question: 'Can independent artists earn royalties without a record label?', answer: 'Yes. Independent artists can release recordings through digital distributors and use publishing, licensing, and rights-management services without signing to a traditional record company.' },
  { question: 'Do Ghanaian artists earn money from streaming platforms?', answer: 'Yes. Eligible recordings can generate revenue through digital music platforms. How money reaches the artist depends on agreements with distributors, labels, publishers, and other rights-management organizations.' },
  { question: 'What is the difference between master and publishing rights?', answer: 'Master rights relate to the sound recording. Publishing rights relate to the underlying song or musical composition. They can belong to different people or companies.' },
  { question: 'Can one song generate several kinds of royalties?', answer: 'Yes. A song may generate income from streaming, broadcasting, public performance, reproduction, licensing, synchronization, and other uses depending on the rights involved.' },
